select , ru.nick_name as receive_user_name, cu.nick_name as create_user_name,

  from sdsorder.u_p_receive_${tableSuffix} r

 where r.shop_code = #{query.shopCode}
 and r.receivecode = #{query.receiveCode}
 and r.purchasecode = #{query.purchaseCode}
 and r.status = #{query.status}

 order by r.createtime desc, r.receivecode desc

